/*
title: $:/plugins/maans/plato/player.css
type: text/css
tags: $:/tags/Stylesheet
*/
.plato-player {
  --plato-gold:#d8b77b; --plato-copper:#b97950; --plato-ink:#101113;
  --plato-soft:#b8b2a8; --plato-line:rgba(216,183,123,.2);
  position:relative; isolation:isolate; width:100%; max-width:1440px; margin:1.2rem auto;
  color:#eee9df; background:#151516; border:1px solid var(--plato-line); border-radius:12px;
  overflow:hidden; box-shadow:0 20px 60px #0004; font-family:system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;
  font-size:15px; line-height:1.5; outline:none;
}
.plato-player *, .plato-player *::before, .plato-player *::after {box-sizing:border-box;}
.plato-player [hidden] {display:none!important;}
.plato-player:focus-visible {outline:2px solid var(--plato-gold);outline-offset:4px;}
.plato-screen {position:relative;width:100%;aspect-ratio:16/9;background:#08090b;overflow:hidden;container-type:inline-size;}
.plato-scene {position:absolute;inset:0;}
.plato-scene>svg {display:block;width:100%;height:100%;max-height:none;max-width:none;}
.plato-scene-badge {
  position:absolute;left:2.5%;top:3%;max-width:85%;padding:.25em .7em;border-radius:2px;
  color:#eee6d8;background:rgba(12,12,14,.58);font-size:clamp(10px,1.05cqw,14px);font-weight:550;
  letter-spacing:.075em;line-height:1.5;pointer-events:none;text-shadow:0 1px 3px #0008;
}
.plato-caption {
  position:absolute;z-index:2;left:6%;right:6%;bottom:4.5%;display:flex;flex-direction:column;
  align-items:center;gap:.32em;pointer-events:none;text-align:center;
}
.plato-caption-speaker {
  display:inline-block;padding:.2em .7em;border-radius:3px;color:#eacb91;background:rgba(9,10,12,.83);
  font-size:clamp(10px,1.2cqw,16px);font-weight:650;letter-spacing:.13em;line-height:1.45;text-transform:uppercase;
}
.plato-caption-text {
  max-width:100%;padding:.4em .85em .48em;border:1px solid rgba(235,222,191,.12);border-radius:5px;
  color:#fff9ed;background:rgba(9,10,12,.87);box-shadow:0 4px 18px #0003;
  font-size:clamp(12px,1.9cqw,27px);font-weight:460;line-height:1.45;white-space:pre-line;
  text-wrap:pretty;text-shadow:0 1px 2px #0009;
}
.plato-caption.is-song .plato-caption-text {color:#ffe0a5;font-style:italic;line-height:1.35;padding:.4em 1.4em;}
.plato-preparing {
  position:absolute;top:3%;right:2.5%;z-index:4;padding:.5em .9em;border:1px solid var(--plato-line);
  border-radius:5px;background:#151516eb;color:#e8cf9b;font-size:13px;
}
.plato-preparing::before {content:"";display:inline-block;width:.75em;height:.75em;margin-right:.6em;border:2px solid #d8b77b40;border-top-color:var(--plato-gold);border-radius:50%;animation:plato-wait 1s linear infinite;}
@keyframes plato-wait {to{transform:rotate(360deg);}}
.plato-transport {display:flex;align-items:center;gap:12px;padding:18px 22px 12px;background:linear-gradient(#1c1b1a,#181819);border-top:1px solid var(--plato-line);}
.plato-player .plato-button {
  display:inline-flex;align-items:center;justify-content:center;flex:none;min-height:39px;padding:8px 13px;
  border:1px solid var(--plato-line);border-radius:6px;color:#ded6c6;background:#232222;
  box-shadow:none;text-shadow:none;font:inherit;font-size:13px;line-height:1.3;white-space:nowrap;cursor:pointer;
  transition:background-color .16s,border-color .16s,color .16s;
}
.plato-player .plato-button:hover {color:#fff7e5;background:#302a23;border-color:#d8b77b80;}
.plato-player .plato-button:focus-visible,.plato-chapters:focus-visible,.plato-player input[type=range]:focus-visible {outline:2px solid var(--plato-gold);outline-offset:3px;}
.plato-player .plato-play {width:116px;min-height:44px;border-color:#d8b77b85;background:#d8b77b;color:#211b13;font-size:15px;font-weight:700;letter-spacing:.01em;}
.plato-player .plato-play:hover {background:#ebcf99;color:#211b13;border-color:#ebcf99;}
.plato-player .plato-stop {width:42px;min-height:44px;padding:7px;font-size:14px;}
.plato-timeline {display:flex;align-items:center;flex:1;gap:16px;min-width:0;}
.plato-player input[type=range] {
  -webkit-appearance:none;appearance:none;display:block;min-width:0;height:24px;padding:0;margin:0;
  border:0;border-radius:0;box-shadow:none;background:transparent;cursor:pointer;accent-color:var(--plato-gold);
}
.plato-player .plato-scrub {width:100%;flex:1;--plato-progress:0%;}
.plato-player input[type=range]::-webkit-slider-runnable-track {height:4px;border-radius:4px;background:#514739;}
.plato-player .plato-scrub::-webkit-slider-runnable-track {background:linear-gradient(to right,var(--plato-gold) 0%,var(--plato-gold) var(--plato-progress),#514739 var(--plato-progress),#514739 100%);}
.plato-player input[type=range]::-moz-range-track {height:4px;border-radius:4px;background:#514739;}
.plato-player input[type=range]::-moz-range-progress {height:4px;border-radius:4px;background:var(--plato-gold);}
.plato-player input[type=range]::-webkit-slider-thumb {-webkit-appearance:none;appearance:none;width:13px;height:13px;margin-top:-4.5px;border:2px solid #e9d2a6;border-radius:50%;background:var(--plato-gold);box-shadow:0 1px 4px #0006;}
.plato-player input[type=range]::-moz-range-thumb {width:10px;height:10px;border:2px solid #e9d2a6;border-radius:50%;background:var(--plato-gold);box-shadow:0 1px 4px #0006;}
.plato-time {flex:none;min-width:105px;color:#c3b9a8;font-size:12px;font-variant-numeric:tabular-nums;letter-spacing:.02em;text-align:right;}
.plato-options {position:relative;display:flex;align-items:center;gap:8px;padding:0 22px 12px;background:#181819;}
.plato-player .plato-chapters {
  display:block;flex:1;min-width:100px;max-width:100%;height:38px;margin:0 4px 0 0;padding:7px 30px 7px 10px;
  border:1px solid var(--plato-line);border-radius:5px;color:#cec2ad;background:#202020;font:inherit;font-size:12px;
  text-overflow:ellipsis;cursor:pointer;
}
.plato-chapters option {background:#202020;color:#eee6d8;}
.plato-player .plato-secondary {min-height:38px;font-size:12px;}
.plato-player .plato-secondary[aria-pressed=true],.plato-player .plato-secondary[aria-expanded=true] {border-color:#b99760;color:#e6c88e;background:#30291f;}
.plato-sound-wrap {position:relative;flex:none;}
.plato-mixer {
  position:absolute;right:0;bottom:calc(100% + 12px);z-index:6;width:285px;padding:15px 17px;
  border:1px solid #8e7553;border-radius:8px;background:#1b1918fa;box-shadow:0 9px 30px #0008;
}
.plato-mixer-row {display:grid;grid-template-columns:43px minmax(90px,1fr) 40px;align-items:center;gap:10px;margin:9px 0;color:#dfd2bb;font-size:12px;}
.plato-player .plato-level {width:100%;}
.plato-level-value {font-size:10px;font-variant-numeric:tabular-nums;color:#a9a08f;text-align:right;}
.plato-footer {padding:0 22px 13px;background:#181819;}
.plato-player .plato-progress {margin:0;color:#a49a8a;font-size:11px;letter-spacing:.03em;line-height:1.5;}
.plato-player .plato-status {min-height:0;margin:0;color:#c5ad86;font-size:12px;line-height:1.5;}
.plato-player .plato-status.has-error {padding-top:7px;}
.plato-load-error,.plato-static {padding:30px;color:#dfc49b;}
.plato-player:fullscreen,.plato-player:-webkit-full-screen {
  display:flex;flex-direction:column;width:100vw;height:100vh;max-width:none;margin:0;border:0;border-radius:0;background:#08090b;
}
.plato-player:fullscreen .plato-screen,.plato-player:-webkit-full-screen .plato-screen {flex:1;min-height:0;aspect-ratio:auto;}
.plato-player:fullscreen .plato-transport,.plato-player:fullscreen .plato-options,.plato-player:fullscreen .plato-footer,
.plato-player:-webkit-full-screen .plato-transport,.plato-player:-webkit-full-screen .plato-options,.plato-player:-webkit-full-screen .plato-footer {flex:none;padding-left:max(22px,env(safe-area-inset-left));padding-right:max(22px,env(safe-area-inset-right));}
.plato-player:fullscreen .plato-footer,.plato-player:-webkit-full-screen .plato-footer {padding-bottom:max(10px,env(safe-area-inset-bottom));}
@media(max-width:700px) {
  .plato-player {border-radius:8px;margin:.7rem auto;}
  .plato-transport {gap:8px;padding:12px 12px 9px;}
  .plato-player .plato-play {width:99px;font-size:13px;}
  .plato-player .plato-stop {width:36px;}
  .plato-timeline {display:block;}
  .plato-time {display:block;min-width:0;font-size:10px;text-align:right;margin-top:1px;}
  .plato-options {flex-wrap:wrap;gap:6px;padding:0 12px 10px;}
  .plato-player .plato-chapters {flex-basis:100%;margin-right:0;}
  .plato-player .plato-secondary {min-height:34px;padding:7px 10px;font-size:11px;}
  .plato-player .plato-fullscreen {margin-left:auto;}
  .plato-footer {padding:0 12px 10px;}
  .plato-progress {font-size:10px!important;}
  .plato-caption {left:4%;right:4%;bottom:4%;gap:3px;}
  .plato-caption-text {font-size:clamp(11px,2.6cqw,20px);line-height:1.35;padding:.35em .6em;}
  .plato-caption-speaker {font-size:clamp(8px,1.6cqw,12px);}
  .plato-mixer {right:-65px;width:260px;}
  .plato-scene-badge {font-size:9px;top:3%;}
  .plato-preparing {font-size:11px;}
}
@media(prefers-reduced-motion:reduce) {.plato-button{transition:none!important;}.plato-preparing::before{animation:none;}}

/* The production opens as an audience programme inside a normal editable wiki. */
body.tc-body {background:#dcd7cc;background-image:radial-gradient(ellipse at 12% 0,#f5efe1,transparent 58%);}
.tc-story-river {max-width:1480px;}
.tc-tiddler-frame {border-radius:9px;box-shadow:0 12px 44px #33281c12;border:1px solid #b6ad982e;}
.tc-tiddler-frame[data-tiddler-title="Turn Around"] {background:#111716;color:#ded9cc;padding:30px 34px 34px;border-color:#81705255;box-shadow:0 20px 70px #211a2338;}
.tc-tiddler-frame[data-tiddler-title="Turn Around"] .tc-titlebar,
.tc-tiddler-frame[data-tiddler-title="Turn Around"] .tc-tags-wrapper {display:none;}
.tc-tiddler-frame[data-tiddler-title="Turn Around"] .tc-tiddler-controls {color:#b5aa91;}
.plato-home {font-family:system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;}
.plato-home .plato-kicker {margin:4px 0 14px;color:#c6a66d;letter-spacing:.2em;font-size:11px;font-weight:650;text-transform:uppercase;}
.plato-home h1 {margin:0;color:#f3e5c6;font:normal clamp(35px,4.1vw,66px)/1.09 Georgia,"Times New Roman",serif;letter-spacing:-.03em;}
.plato-home .plato-subtitle {margin:12px 0 6px;color:#bcb9aa;font-size:17px;line-height:1.6;}
.plato-home .plato-description {max-width:840px;margin:0;color:#c1c1b3;font-size:14px;line-height:1.65;}
.plato-nav {display:flex;flex-wrap:wrap;align-items:center;gap:9px 20px;margin:20px 0 4px;font:500 13px/1.5 system-ui,sans-serif;}
.plato-home .plato-nav a {color:#e3c18b;text-decoration:none;border-bottom:1px solid #9c825d6e;padding:5px 0;}
.plato-home .plato-nav a:hover {color:#fff0ce;border-bottom-color:#fff0ce;}
.plato-home .plato-nav .plato-native-link a {border:1px solid #a88e5f85;border-radius:5px;padding:7px 13px;background:#d8b77b14;}
.plato-home .plato-hint {color:#aaa99c;font-size:12px;line-height:1.7;margin:15px 0 0;}
.plato-home .plato-hint strong {color:#d6ccb6;font-weight:600;}
.plato-home .plato-programme {display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:26px;margin-top:30px;padding-top:23px;border-top:1px solid #b19c6c33;}
.plato-home .plato-programme h3 {font:normal 24px/1.3 Georgia,serif;color:#dfc89d;margin:0 0 10px;}
.plato-home .plato-programme p {font-size:13px;line-height:1.75;margin:0;color:#aaa99e;}
.plato-home .plato-programme .plato-number {display:block;font:600 10px/1.5 system-ui,sans-serif;letter-spacing:.17em;color:#947b53;margin-bottom:7px;}
.plato-home .plato-colophon {margin-top:24px;color:#8e9389;font-size:11px;line-height:1.7;}
.plato-page-intro {max-width:860px;font-size:16px;line-height:1.75;margin-bottom:24px;}
.plato-scene-list {display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;}
.plato-scene-card {padding:16px 19px;border:1px solid #d4cbbb;border-radius:5px;background:#fbf8f1;}
.plato-scene-card h3 {font:500 19px/1.35 Georgia,serif;margin:0 0 8px;color:#3c362c;}
.plato-scene-card p {font-size:12px;line-height:1.6;margin:5px 0;}
.plato-scene-card .plato-timecode {font:600 10px/1.5 system-ui,sans-serif;letter-spacing:.12em;color:#8d7250;}
.plato-credits {max-width:900px;line-height:1.75;}
.plato-credits h2 {font:500 26px/1.4 Georgia,serif;margin:30px 0 14px;}
.plato-credits h3 {margin-top:24px;}
.plato-credits li {margin:9px 0;}
.plato-script-text {max-width:850px;}
.plato-script-text .plato-script-label {font-size:11px;letter-spacing:.07em;font-weight:700;color:#7e633f;margin:18px 0 3px;}
.plato-script-text .plato-script-line {font-size:16px;line-height:1.7;margin:0 0 9px;}
.plato-script-text .is-song {font-style:italic;white-space:pre-line;color:#67502b;}
.plato-script-text .plato-stage-note {color:#6b6a61;font-size:13px;line-height:1.7;}
@media(min-width:960px) {.tc-story-river {width:calc(100vw - 80px);margin:40px auto;padding:0;}}
@media(max-width:700px) {
 .tc-tiddler-frame[data-tiddler-title="Turn Around"] {padding:23px 13px;}
 .plato-home .plato-subtitle {font-size:15px;}
 .plato-home .plato-description {font-size:12px;}
 .plato-home .plato-programme {grid-template-columns:1fr;gap:22px;}
 .plato-scene-list {grid-template-columns:1fr;}
 .plato-home .plato-nav {gap:8px 15px;font-size:12px;}
}
@media print {.plato-nav,.plato-player{display:none!important;}.tc-tiddler-frame{box-shadow:none;}}
